function normalizeOptionalNumber(value: unknown): number | undefined {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.round(value);
  }
  return undefined;
}

export function normalizeFlightCue(value: unknown): FlightCue | null {
  if (!isRecord(value)) {
    return null;
  }

  const kind = value.kind;
  if (typeof kind !== 'string' || !VALID_CUE_KINDS.has(kind as FlightCueKind)) {
    return null;
  }

  const cue: FlightCue = {
    id: typeof value.id === 'string' && value.id.trim().length > 0 ? value.id.trim() : createId('cue'),
    kind: kind as FlightCueKind,
    label: normalizeOptionalString(value.label)
  };

  if (typeof value.isFiller === 'boolean') cue.isFiller = value.isFiller;
  const clockOffsetSeconds = normalizeOptionalNumber(value.clockOffsetSeconds);
  if (clockOffsetSeconds !== undefined) cue.clockOffsetSeconds = clockOffsetSeconds;
  const voiceTrackInstantId = normalizeOptionalNumber(value.voiceTrackInstantId);
  if (voiceTrackInstantId !== undefined) cue.voiceTrackInstantId = voiceTrackInstantId;
  for (const field of ['voiceDuckGain', 'voiceFadeInSeconds', 'voiceFadeOutSeconds'] as const) {
    if (typeof value[field] === 'number' && Number.isFinite(value[field])) cue[field] = value[field] as number;
  }

  const sceneId = normalizeOptionalNumber(value.sceneId);
  if (sceneId !== undefined) {
    cue.sceneId = sceneId;
  }

  const transitionId = normalizeOptionalString(value.transitionId);
  if (transitionId !== undefined) {
    cue.transitionId = transitionId;
  }

  const songId = normalizeOptionalNumber(value.songId);
  if (songId !== undefined) {
    cue.songId = songId;
  }

  const durationMs = normalizeOptionalNumber(value.durationMs);
  if (durationMs !== undefined && durationMs >= 0) {
    cue.durationMs = durationMs;
  }

  if (isRecord(value.metadataPatch)) {
    cue.metadataPatch = value.metadataPatch as Record<string, unknown>;
  }

  const instantId = normalizeOptionalNumber(value.instantId);
  if (instantId !== undefined) {
    cue.instantId = instantId;
  }

  if (isRecord(value.mixerChange)) {
    const change: FlightMixerChange = {};
    const channelId = value.mixerChange.channelId;
    if (VALID_MIXER_CHANNEL_IDS.has(channelId as FlightMixerChange['channelId'])) {
      change.channelId = channelId as FlightMixerChange['channelId'];
    }
    // A fraction (0-1, the rundown editor's step is 0.05), kept as given like
    // the backend's flight normaliser does: rounding it made 0.4 silent (#244).
    const volume = value.mixerChange.volume;
    if (typeof volume === 'number' && Number.isFinite(volume)) {
      change.volume = volume;
    }
    if (typeof value.mixerChange.muted === 'boolean') {
      change.muted = value.mixerChange.muted;
    }
    if (typeof value.mixerChange.solo === 'boolean') {
      change.solo = value.mixerChange.solo;
    }
    cue.mixerChange = change;
  }

  return cue;
}

export function normalizeFlightSequence(value: unknown): FlightSequence | null {
  if (!isRecord(value)) {
    return null;
  }

  const rawItems = Array.isArray(value.items) ? value.items : [];
  const items = rawItems
    .map(normalizeFlightCue)
    .filter((cue): cue is FlightCue => cue !== null);

  return {
    id: typeof value.id === 'number' && Number.isFinite(value.id) ? value.id : 0,
    name: typeof value.name === 'string' ? value.name : 'Unnamed',
    items,
    loop: value.loop === true,
    isRunning: value.isRunning === true,
    activeItemId: value.activeItemId === null || typeof value.activeItemId === 'string' ? value.activeItemId : null,
    scheduledAt: typeof value.scheduledAt === 'string' ? value.scheduledAt : null,
    publishedAt: typeof value.publishedAt === 'string' ? value.publishedAt : null,
    lastStartedAt: typeof value.lastStartedAt === 'string' ? value.lastStartedAt : null,
    revision: typeof value.revision === 'number' && Number.isInteger(value.revision) ? value.revision : 1,
    createdAt: typeof value.createdAt === 'string' ? value.createdAt : new Date().toISOString(),
    updatedAt: typeof value.updatedAt === 'string' ? value.updatedAt : new Date().toISOString()
  };
}

export function createFlightCue(kind: FlightCueKind = 'wait'): FlightCue {
  const cue: FlightCue = {
    id: createId('cue'),
    kind
  };

  if (kind === 'wait') {
    cue.durationMs = 3000;
  }

  if (kind === 'scene') {
    cue.transitionId = 'cut';
  }

  return cue;
}

export function getFlightCueDisplayLabel(
  cue: FlightCue,
  context?: {
    scenes?: { id: number; name: string }[];
    songs?: { id: number; title: string; artist: string }[];
    instants?: { id: number; name: string }[];
  }
): string {
  if (cue.label) {
    return cue.label;
  }

  switch (cue.kind) {
    case 'scene':
      if (cue.sceneId !== undefined) {
        const scene = context?.scenes?.find((s) => s.id === cue.sceneId);
        return scene ? `Scene: ${scene.name}` : `Scene ${cue.sceneId}`;
      }
      return 'Scene';
    case 'playSong':
      if (cue.songId !== undefined) {
        const song = context?.songs?.find((s) => s.id === cue.songId);
        return song ? `Play: ${song.artist} - ${song.title}` : `Play song ${cue.songId}`;
      }
      return 'Play song';
    case 'stopSong':
      return 'Stop song';
    case 'wait':
      return cue.durationMs !== undefined ? `Wait ${cue.durationMs}ms` : 'Wait';
    case 'waitForSongEnd':
      return 'Wait for song end';
    case 'sceneUpdate':
      return cue.sceneId !== undefined ? `Update scene ${cue.sceneId}` : 'Update scene';
    case 'instant':
      if (cue.instantId !== undefined) {
        const instant = context?.instants?.find((i) => i.id === cue.instantId);
        return instant ? `Instant: ${instant.name}` : `Instant ${cue.instantId}`;
      }
      return 'Instant';
    case 'mixer':
      if (cue.mixerChange?.channelId) {
        const parts: string[] = [cue.mixerChange.channelId];
        if (typeof cue.mixerChange.volume === 'number') parts.push(`vol ${Math.round(cue.mixerChange.volume * 100)}%`);
        if (typeof cue.mixerChange.muted === 'boolean') parts.push(cue.mixerChange.muted ? 'mute' : 'unmute');
        if (typeof cue.mixerChange.solo === 'boolean') parts.push(cue.mixerChange.solo ? 'solo' : 'unsolo');
        return `Mixer: ${parts.join(' ')}`;
      }
      return 'Mixer';
    default:
      return 'Cue';
  }
}

import type { FlightCue, FlightSequence } from './flight.types';
import type {
  FlightDesiredState,
  FlightMixerChannelState,
} from './flight-resolver.types';

/**
 * Pure rundown resolver (gaulatti/alcantara#152).
 *
 * Given a sequence, the time it started and the current time, it computes what
 * should be on air, without I/O, without reading a clock and without mutating
 * its inputs. Nothing calls it yet; the executor in `flight.service.ts` still
 * runs rundowns with timers.
 *
 * Cues take effect in order:
 * - `scene` puts its scene on Program and clears the accumulated patches.
 * - `sceneUpdate` merges its `metadataPatch` into the patches of the scene on
 *   Program (a patch naming another scene is ignored).
 * - `mixer` sets the named channel; `main` takes only a volume, as the executor
 *   does, and a change without a channel is ignored.
 * - `playSong` starts its song at position 0; `stopSong` stops it. A song with
 *   a known duration is over once that duration has played.
 * - `instant` changes nothing here.
 * - `wait` consumes `durationMs`; `waitForSongEnd` consumes what remains of the
 *   current song, or nothing when no song plays or its duration is unknown.
 *   Every other cue consumes no time.
 *
 * A looping sequence starts over after its last cue and its elapsed time wraps;
 * a sequence whose passes consume no time returns after one pass. A
 * non-looping sequence is final, and `finished`, after its last cue.
 */
/** A song started at `startMs` on the sequence's own timeline. */
interface PlayingSong {
  songId: number | null;
  startMs: number;
}

export function resolve(
  sequence: Pick<FlightSequence, 'items' | 'loop'>,
  startedAtMs: number,
  nowMs: number,
  songDurationsMs: ReadonlyMap<number, number>,
): FlightDesiredState {
  const state = emptyState();
  const elapsed = nowMs - startedAtMs;
  // Before the start (or on a clock that is not a finite time) nothing is on air.
  if (!Number.isFinite(elapsed) || elapsed < 0) return state;

  const cues = sequence.items;
  // Held in an object so the cue callbacks and the loop share one current song.
  const playback: { song: PlayingSong | null } = { song: null };
  let t = 0;

  /** A song's duration when it is known as a finite, non-negative number. */
  const durationOf = (songId: number | null) => {
    const duration = songId === null ? undefined : songDurationsMs.get(songId);
    return duration !== undefined && Number.isFinite(duration) && duration >= 0
      ? duration
      : undefined;
  };
  /** The playing song at time `at`, or null once a known duration has played. */
  const songAt = (at: number): PlayingSong | null => {
    const song = playback.song;
    if (!song) return null;
    const duration = durationOf(song.songId);
    return duration !== undefined && at - song.startMs >= duration ? null : song;
  };
  const finish = (at: number): FlightDesiredState => {
    const playing = songAt(at);
    state.song = playing && {
      songId: playing.songId,
      positionMs: at - playing.startMs,
    };
    return state;
  };

  // Only the song in progress changes how long a pass takes, so a pass that
  // starts with the same song state as an earlier one repeats it exactly.
  const passStarts = new Map<string, number>();
  for (;;) {
    if (sequence.loop) {
      const playing = songAt(t);
      const duration = playing ? durationOf(playing.songId) : undefined;
      const key = !playing
        ? 'none'
        : duration === undefined
          ? `unknown:${playing.songId}`
          : `remaining:${playing.startMs + duration - t}`;
      const previous = passStarts.get(key);
      if (previous !== undefined) {
        const period = t - previous;
        if (period === 0) return finish(elapsed);
        const skipped = Math.floor((elapsed - t) / period) * period;
        t += skipped;
        if (playback.song) playback.song.startMs += skipped;
      }
      passStarts.set(key, t);
    }

    for (const cue of cues) {
      apply(state, cue, t, (next) => {
        playback.song = next;
      });
      const consumed = consumes(cue, songAt(t), t, durationOf);
      if (elapsed < t + consumed) return finish(elapsed);
      t += consumed;
    }

    if (!sequence.loop) {
      state.finished = true;
      state.activeCueId = null;
      return finish(elapsed);
    }
  }
}

function emptyState(): FlightDesiredState {
  return {
    scene: null,
    sceneMetadataPatch: {},
    song: null,
    mixer: {},
    activeCueId: null,
    finished: false,
  };
}

function apply(
  state: FlightDesiredState,
  cue: FlightCue,
  at: number,
  setSong: (song: PlayingSong | null) => void,
): void {
  state.activeCueId = cue.id;
  switch (cue.kind) {
    case 'scene':
      if (typeof cue.sceneId === 'number') {
        state.scene = { sceneId: cue.sceneId, transitionId: cue.transitionId ?? null };
        state.sceneMetadataPatch = {};
      }
      break;
    case 'sceneUpdate':
      if (
        state.scene &&
        isRecord(cue.metadataPatch) &&
        (cue.sceneId === undefined || cue.sceneId === state.scene.sceneId)
      ) {
        state.sceneMetadataPatch = { ...state.sceneMetadataPatch, ...cue.metadataPatch };
      }
      break;
    case 'mixer': {
      const change = cue.mixerChange;
      const channel = change?.channelId;
      if (!channel) break;
      const level =
        channel === 'main'
          ? pick(change, ['volume'])
          : pick(change, ['volume', 'muted', 'solo']);
      if (Object.keys(level).length === 0) break;
      state.mixer = { ...state.mixer, [channel]: { ...state.mixer[channel], ...level } };
      break;
    }
    case 'playSong':
      setSong({ songId: typeof cue.songId === 'number' ? cue.songId : null, startMs: at });
      break;
    case 'stopSong':
      setSong(null);
      break;
    default:
      break;
  }
}

function consumes(
  cue: FlightCue,
  playing: PlayingSong | null,
  at: number,
  durationOf: (songId: number | null) => number | undefined,
): number {
  if (cue.kind === 'wait') {
    return typeof cue.durationMs === 'number' && cue.durationMs > 0 ? cue.durationMs : 0;
  }
  if (cue.kind === 'waitForSongEnd' && playing) {
    const duration = durationOf(playing.songId);
    return duration === undefined ? 0 : playing.startMs + duration - at;
  }
  return 0;
}

/** The listed fields of a mixer change that are set. */
function pick(
  change: NonNullable<FlightCue['mixerChange']>,
  fields: Array<keyof FlightMixerChannelState>,
): FlightMixerChannelState {
  const level: FlightMixerChannelState = {};
  for (const field of fields) {
    if (change[field] !== undefined) Object.assign(level, { [field]: change[field] });
  }
  return level;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

import { resolve } from './flight-resolver';
import type { FlightCue } from './flight.types';
// The desired-state module holds only types; load it so coverage measures it, as
// flight.service.coverage-clock.spec.ts does for flight.types.ts.
import './flight-resolver.types';

const START = 1_800_000_000_000;
const NO_DURATIONS = new Map<number, number>();

const sequence = (items: FlightCue[], loop = false) => ({ items, loop });
const at = (ms: number) => START + ms;

const empty = {
  scene: null,
  sceneMetadataPatch: {},
  song: null,
  mixer: {},
  activeCueId: null,
  finished: false,
};

describe('flight resolver', () => {
  it('returns the empty state before the start and on a clock that is not finite', () => {
    const seq = sequence([{ id: 'take', kind: 'scene', sceneId: 1 }]);
    expect(resolve(seq, START, at(-1), NO_DURATIONS)).toEqual(empty);
    expect(resolve(seq, START, Number.NaN, NO_DURATIONS)).toEqual(empty);
    expect(resolve(seq, START, Number.POSITIVE_INFINITY, NO_DURATIONS)).toEqual(empty);
  });

  it('takes a scene with its transition and clears earlier patches', () => {
    const seq = sequence([
      { id: 'a', kind: 'scene', sceneId: 1 },
      { id: 'patch', kind: 'sceneUpdate', sceneId: 1, metadataPatch: { headline: 'Old' } },
      { id: 'b', kind: 'scene', sceneId: 2, transitionId: 'wipe' },
      { id: 'hold', kind: 'wait', durationMs: 1000 },
    ]);
    expect(resolve(seq, START, at(0), NO_DURATIONS)).toEqual({
      ...empty,
      scene: { sceneId: 2, transitionId: 'wipe' },
      activeCueId: 'hold',
    });
  });

  it('ignores a scene cue without a scene', () => {
    const seq = sequence([
      { id: 'a', kind: 'scene', sceneId: 1 },
      { id: 'broken', kind: 'scene' },
      { id: 'hold', kind: 'wait', durationMs: 10 },
    ]);
    expect(resolve(seq, START, at(5), NO_DURATIONS).scene).toEqual({ sceneId: 1, transitionId: null });
  });

  it('merges scene updates for the scene on Program, in order, and ignores the rest', () => {
    const seq = sequence([
      { id: 'early', kind: 'sceneUpdate', sceneId: 1, metadataPatch: { before: true } },
      { id: 'take', kind: 'scene', sceneId: 1 },
      { id: 'p1', kind: 'sceneUpdate', sceneId: 1, metadataPatch: { headline: 'First', ticker: 'On' } },
      { id: 'p2', kind: 'sceneUpdate', metadataPatch: { headline: 'Second' } },
      { id: 'other', kind: 'sceneUpdate', sceneId: 9, metadataPatch: { headline: 'Elsewhere' } },
      { id: 'bad', kind: 'sceneUpdate', sceneId: 1 },
      { id: 'list', kind: 'sceneUpdate', sceneId: 1, metadataPatch: ['x'] as unknown as Record<string, unknown> },
      { id: 'hold', kind: 'wait', durationMs: 10 },
    ]);
    expect(resolve(seq, START, at(1), NO_DURATIONS).sceneMetadataPatch).toEqual({ headline: 'Second', ticker: 'On' });
  });

  it('sets each named mixer channel; main takes only a volume; unnamed changes are ignored', () => {
    const seq = sequence([
      { id: 'm1', kind: 'mixer', mixerChange: { channelId: 'song', volume: 0.4 } },
      { id: 'm2', kind: 'mixer', mixerChange: { channelId: 'song', muted: true } },
      { id: 'm3', kind: 'mixer', mixerChange: { channelId: 'stream', solo: true, volume: 1 } },
      { id: 'm4', kind: 'mixer', mixerChange: { channelId: 'main', volume: 0.8, muted: true } },
      { id: 'm5', kind: 'mixer', mixerChange: { channelId: 'main', muted: true } },
      { id: 'm6', kind: 'mixer', mixerChange: { volume: 0.1 } },
      { id: 'm7', kind: 'mixer' },
      { id: 'hold', kind: 'wait', durationMs: 10 },
    ]);
    expect(resolve(seq, START, at(1), NO_DURATIONS).mixer).toEqual({
      song: { volume: 0.4, muted: true },
      stream: { volume: 1, solo: true },
      main: { volume: 0.8 },
    });
  });

  it('starts a song at position 0, plays it on, and stops it', () => {
    const seq = sequence([
      { id: 'play', kind: 'playSong', songId: 7 },
      { id: 'hold', kind: 'wait', durationMs: 5000 },
      { id: 'stop', kind: 'stopSong' },
      { id: 'after', kind: 'wait', durationMs: 5000 },
    ]);
    expect(resolve(seq, START, at(0), NO_DURATIONS).song).toEqual({ songId: 7, positionMs: 0 });
    expect(resolve(seq, START, at(2500), NO_DURATIONS).song).toEqual({ songId: 7, positionMs: 2500 });
    expect(resolve(seq, START, at(6000), NO_DURATIONS)).toMatchObject({ song: null, activeCueId: 'after' });
  });

  it('plays a song without a song id with no known duration', () => {
    const seq = sequence([
      { id: 'play', kind: 'playSong' },
      { id: 'end', kind: 'waitForSongEnd' },
      { id: 'hold', kind: 'wait', durationMs: 100 },
    ]);
    expect(resolve(seq, START, at(50), NO_DURATIONS)).toMatchObject({ song: { songId: null, positionMs: 50 }, activeCueId: 'hold' });
  });

  it('ends a song with a known duration once it has played', () => {
    const seq = sequence([
      { id: 'play', kind: 'playSong', songId: 7 },
      { id: 'hold', kind: 'wait', durationMs: 10_000 },
    ]);
    const durations = new Map([[7, 3000]]);
    expect(resolve(seq, START, at(2999), durations).song).toEqual({ songId: 7, positionMs: 2999 });
    expect(resolve(seq, START, at(3000), durations).song).toBeNull();
  });

  it('changes nothing for an instant cue', () => {
    const seq = sequence([
      { id: 'take', kind: 'scene', sceneId: 1 },
      { id: 'hold', kind: 'wait', durationMs: 10 },
      { id: 'bell', kind: 'instant', instantId: 3 },
      { id: 'after', kind: 'wait', durationMs: 10 },
    ]);
    const before = resolve(seq, START, at(5), NO_DURATIONS);
    const after = resolve(seq, START, at(15), NO_DURATIONS);
    expect({ ...after, activeCueId: before.activeCueId }).toEqual(before);
  });

  it('holds a wait until its last millisecond and moves on at its end', () => {
    const seq = sequence([
      { id: 'hold', kind: 'wait', durationMs: 1000 },
      { id: 'take', kind: 'scene', sceneId: 4 },
      { id: 'next', kind: 'wait', durationMs: 1000 },
    ]);
    expect(resolve(seq, START, at(999), NO_DURATIONS)).toMatchObject({ activeCueId: 'hold', scene: null });
    expect(resolve(seq, START, at(1000), NO_DURATIONS)).toMatchObject({ activeCueId: 'next', scene: { sceneId: 4 } });
    expect(resolve(seq, START, at(1001), NO_DURATIONS)).toMatchObject({ activeCueId: 'next', scene: { sceneId: 4 } });
  });

  it('treats a wait without a positive duration as taking no time', () => {
    const seq = sequence([
      { id: 'none', kind: 'wait' },
      { id: 'negative', kind: 'wait', durationMs: -5 },
      { id: 'hold', kind: 'wait', durationMs: 10 },
    ]);
    expect(resolve(seq, START, at(0), NO_DURATIONS).activeCueId).toBe('hold');
  });

  it('waits for the rest of a song with a known duration', () => {
    const seq = sequence([
      { id: 'play', kind: 'playSong', songId: 7 },
      { id: 'intro', kind: 'wait', durationMs: 1000 },
      { id: 'end', kind: 'waitForSongEnd' },
      { id: 'take', kind: 'scene', sceneId: 2 },
    ]);
    const durations = new Map([[7, 4000]]);
    expect(resolve(seq, START, at(3999), durations)).toMatchObject({ activeCueId: 'end', song: { songId: 7, positionMs: 3999 } });
    expect(resolve(seq, START, at(4000), durations)).toMatchObject({ finished: true, song: null, scene: { sceneId: 2 } });
  });

  it('does not wait for a song with an unknown or unusable duration, or when none plays', () => {
    const seq = (songId: number) => sequence([
      { id: 'play', kind: 'playSong', songId },
      { id: 'end', kind: 'waitForSongEnd' },
      { id: 'take', kind: 'scene', sceneId: 2 },
      { id: 'hold', kind: 'wait', durationMs: 100 },
    ]);
    const durations = new Map([[8, Number.NaN], [9, -1]]);
    for (const songId of [7, 8, 9]) {
      expect(resolve(seq(songId), START, at(0), durations)).toMatchObject({ activeCueId: 'hold', scene: { sceneId: 2 } });
    }
    const silent = sequence([
      { id: 'end', kind: 'waitForSongEnd' },
      { id: 'take', kind: 'scene', sceneId: 3 },
      { id: 'hold', kind: 'wait', durationMs: 100 },
    ]);
    expect(resolve(silent, START, at(0), NO_DURATIONS).scene).toEqual({ sceneId: 3, transitionId: null });
  });

  it('is final and finished after the last cue of a non-looping sequence', () => {
    const seq = sequence([
      { id: 'take', kind: 'scene', sceneId: 1 },
      { id: 'play', kind: 'playSong', songId: 7 },
      { id: 'hold', kind: 'wait', durationMs: 1000 },
    ]);
    expect(resolve(seq, START, at(5000), NO_DURATIONS)).toEqual({
      ...empty,
      scene: { sceneId: 1, transitionId: null },
      song: { songId: 7, positionMs: 5000 },
      finished: true,
    });
    expect(resolve(sequence([]), START, at(0), NO_DURATIONS)).toEqual({ ...empty, finished: true });
  });

  it('wraps elapsed time when the sequence loops', () => {
    const seq = sequence([
      { id: 'a', kind: 'scene', sceneId: 1 },
      { id: 'holdA', kind: 'wait', durationMs: 1000 },
      { id: 'b', kind: 'scene', sceneId: 2 },
      { id: 'holdB', kind: 'wait', durationMs: 500 },
    ], true);
    expect(resolve(seq, START, at(1499), NO_DURATIONS)).toMatchObject({ activeCueId: 'holdB', scene: { sceneId: 2 } });
    expect(resolve(seq, START, at(1500), NO_DURATIONS)).toMatchObject({ activeCueId: 'holdA', scene: { sceneId: 1 }, finished: false });
    // A day in, 86,400,000 ms = 57,600 whole cycles: back at the start of a cycle.
    expect(resolve(seq, START, at(86_400_000), NO_DURATIONS)).toMatchObject({ activeCueId: 'holdA', scene: { sceneId: 1 } });
    expect(resolve(seq, START, at(86_400_000 + 1200), NO_DURATIONS)).toMatchObject({ activeCueId: 'holdB' });
  });

  it('carries a song across the loop and keeps its position', () => {
    const seq = sequence([
      { id: 'end', kind: 'waitForSongEnd' },
      { id: 'play', kind: 'playSong', songId: 7 },
      { id: 'hold', kind: 'wait', durationMs: 1000 },
    ], true);
    const durations = new Map([[7, 3000]]);
    // Cycle 1: 0-1000 hold. Cycle 2: 1000-3000 waits for the song's last 2000 ms,
    // then restarts it; from then on every cycle lasts the song's 3000 ms.
    expect(resolve(seq, START, at(2500), durations)).toMatchObject({ activeCueId: 'end', song: { songId: 7, positionMs: 2500 } });
    expect(resolve(seq, START, at(3500), durations)).toMatchObject({ activeCueId: 'hold', song: { songId: 7, positionMs: 500 } });
    expect(resolve(seq, START, at(3000 + 3000 * 1000 + 200), durations)).toMatchObject({ activeCueId: 'hold', song: { songId: 7, positionMs: 200 } });
    expect(resolve(seq, START, at(3000 + 3000 * 1000 + 2200), durations)).toMatchObject({ activeCueId: 'end', song: { songId: 7, positionMs: 2200 } });
  });

  it('keeps a song with an unknown duration playing across a looping sequence', () => {
    const seq = sequence([
      { id: 'play', kind: 'playSong', songId: 5 },
      { id: 'hold', kind: 'wait', durationMs: 1000 },
      { id: 'stop', kind: 'stopSong' },
      { id: 'gap', kind: 'wait', durationMs: 1000 },
    ], true);
    expect(resolve(seq, START, at(2000 * 50 + 300), NO_DURATIONS)).toMatchObject({ activeCueId: 'hold', song: { songId: 5, positionMs: 300 } });
    expect(resolve(seq, START, at(2000 * 50 + 1300), NO_DURATIONS)).toMatchObject({ activeCueId: 'gap', song: null });
  });

  it('restarts a song with an unknown duration on every pass of a loop', () => {
    const seq = sequence([
      { id: 'hold', kind: 'wait', durationMs: 1000 },
      { id: 'play', kind: 'playSong', songId: 5 },
    ], true);
    expect(resolve(seq, START, at(2500), NO_DURATIONS)).toMatchObject({ activeCueId: 'hold', song: { songId: 5, positionMs: 500 } });
    expect(resolve(seq, START, at(1000 * 500 + 250), NO_DURATIONS)).toMatchObject({ activeCueId: 'hold', song: { songId: 5, positionMs: 250 } });
  });

  it('returns after one pass when a looping sequence consumes no time', () => {
    const seq = sequence([
      { id: 'take', kind: 'scene', sceneId: 1 },
      { id: 'bell', kind: 'instant', instantId: 2 },
      { id: 'end', kind: 'waitForSongEnd' },
    ], true);
    expect(resolve(seq, START, at(60_000), NO_DURATIONS)).toEqual({
      ...empty,
      scene: { sceneId: 1, transitionId: null },
      activeCueId: 'end',
      finished: false,
    });
    expect(resolve(sequence([], true), START, at(10), NO_DURATIONS)).toEqual(empty);
  });

  it('is deterministic and never mutates its inputs', () => {
    const items: FlightCue[] = [
      { id: 'take', kind: 'scene', sceneId: 1, transitionId: 'cut' },
      { id: 'patch', kind: 'sceneUpdate', sceneId: 1, metadataPatch: { headline: 'A', nested: { deep: [1, 2] } } },
      { id: 'mix', kind: 'mixer', mixerChange: { channelId: 'song', volume: 0.5 } },
      { id: 'play', kind: 'playSong', songId: 7 },
      { id: 'end', kind: 'waitForSongEnd' },
      { id: 'hold', kind: 'wait', durationMs: 750 },
    ];
    const durations = new Map([[7, 2000], [8, 100]]);
    const seqs = [sequence(items, false), sequence(items, true)];
    for (const seq of seqs) {
      const original = structuredClone({ seq, durations: [...durations] });
      for (let i = 0; i < 200; i += 1) {
        const startedAtMs = START + ((i * 7919) % 5000) - 2500;
        const nowMs = START + ((i * 104_729) % 20_000);
        const first = resolve(seq, startedAtMs, nowMs, durations);
        const second = resolve(seq, startedAtMs, nowMs, durations);
        expect(second).toEqual(first);
      }
      expect({ seq, durations: [...durations] }).toEqual(original);
    }
  });
});

