function apply(
  state: FlightDesiredState,
  cue: FlightCue,
  at: number,
  setSong: (song: PlayingSong | null) => void,
): void {
  state.activeCueId = cue.id;
  switch (cue.kind) {
    case 'scene':
      if (typeof cue.sceneId === 'number') {
        state.scene = { sceneId: cue.sceneId, transitionId: cue.transitionId ?? null };
        state.sceneMetadataPatch = {};
      }
      break;
    case 'sceneUpdate':
      if (
        state.scene &&
        isRecord(cue.metadataPatch) &&
        (cue.sceneId === undefined || cue.sceneId === state.scene.sceneId)
      ) {
        state.sceneMetadataPatch = { ...state.sceneMetadataPatch, ...cue.metadataPatch };
      }
      break;
    case 'mixer': {
      const change = cue.mixerChange;
      const channel = change?.channelId;
      if (!channel) break;
      const level =
        channel === 'main'
          ? pick(change, ['volume'])
          : pick(change, ['volume', 'muted', 'solo']);
      if (Object.keys(level).length === 0) break;
      state.mixer = { ...state.mixer, [channel]: { ...state.mixer[channel], ...level } };

    const channels = Array.isArray(settings.mixerChannels)
      ? settings.mixerChannels
      : [];
    const nextChannels = channels.map((channel: unknown) => {
      const record = isRecord(channel) ? channel : {};
      if (record.id !== mixerChange.channelId) {
        return record;
      }
      const next: Record<string, unknown> = { ...record };
      if (typeof mixerChange.volume === 'number') {
        next.volume = mixerChange.volume;
      }
      if (typeof mixerChange.muted === 'boolean') {
        next.muted = mixerChange.muted;
      }
      if (typeof mixerChange.solo === 'boolean') {
        next.solo = mixerChange.solo;
      }
      return next;
    });
    patch.mixerChannels = nextChannels;
  }

  if (Object.keys(patch).length === 0) {
    return;
  }

  await this.programService.updateProgramAudioBus(
    { mixerSettings: patch },
    programId,
  );
}

